#!/usr/bin/env python3
"""Count lines, words and characters in text files and print a table or JSON."""

import json
import os
import sys


def count_text(text):
    lines = text.count("\n")
    if text and not text.endswith("\n"):
        lines += 1
    words = len(text.split())
    chars = len(text)
    return lines, words, chars


def count_file(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        text = f.read()
    return count_text(text)


def count_stdin():
    data = sys.stdin.buffer.read()
    return count_text(data.decode("utf-8"))


def main(argv):
    prog = os.path.basename(argv[0]) if argv else "wordcount.py"
    as_json = "--json" in argv[1:]
    files = [a for a in argv[1:] if a != "--json"]
    if not files:
        print(f"usage: {prog} FILE [FILE ...]", file=sys.stderr)
        return 2

    rows = []
    had_error = False
    for path in files:
        try:
            if path == "-":
                lines, words, chars = count_stdin()
            else:
                if not os.path.isfile(path):
                    raise OSError
                lines, words, chars = count_file(path)
            rows.append((path, lines, words, chars))
        except OSError:
            print(f"{prog}: cannot read {path}", file=sys.stderr)
            had_error = True

    if as_json:
        obj = {
            "files": [
                {"file": path, "lines": lines, "words": words, "chars": chars}
                for path, lines, words, chars in rows
            ],
            "total": {
                "lines": sum(r[1] for r in rows),
                "words": sum(r[2] for r in rows),
                "chars": sum(r[3] for r in rows),
            },
        }
        print(json.dumps(obj, indent=2))
        return 1 if had_error else 0

    if not rows:
        return 1

    header = ("lines", "words", "chars", "file")
    out = [header]
    for path, lines, words, chars in rows:
        out.append((str(lines), str(words), str(chars), path))
    if len(rows) >= 2:
        total = (str(sum(r[1] for r in rows)),
                 str(sum(r[2] for r in rows)),
                 str(sum(r[3] for r in rows)),
                 "total")
        out.append(total)

    widths = [max(len(r[i]) for r in out) for i in range(3)]
    for r in out:
        print(f"{r[0]:>{widths[0]}}  {r[1]:>{widths[1]}}  {r[2]:>{widths[2]}}  {r[3]}")

    return 1 if had_error else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
