#!/usr/bin/env python3
"""Print lines of a log file at a given level."""

import argparse
import sys

LEVELS = ["INFO", "WARN", "ERROR"]


def usage_error(message):
    print(f"logscan.py: {message}", file=sys.stderr)
    print(
        "usage: logscan.py PATH LEVEL [--at-least] [--limit N]",
        file=sys.stderr,
    )
    sys.exit(2)


class UsageError(Exception):
    pass


class ArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        raise UsageError(message)

    def exit(self, status=0, message=None):
        if status:
            raise UsageError(message or "")


def parse_args(argv):
    parser = ArgumentParser(
        prog="logscan.py",
        usage="logscan.py PATH LEVEL [--at-least] [--limit N]",
    )
    parser.add_argument("path")
    parser.add_argument("level")
    parser.add_argument("--at-least", action="store_true")
    parser.add_argument("--limit", type=int, default=None)
    try:
        args = parser.parse_args(argv)
    except UsageError as exc:
        usage_error(str(exc))
    if args.limit is not None and args.limit < 0:
        usage_error("argument --limit: must be >= 0")
    return args


def main(argv=None):
    args = parse_args(sys.argv[1:] if argv is None else argv)

    wanted = args.level.upper()
    if wanted not in LEVELS:
        usage_error(f"invalid level: {args.level!r}")

    wanted_rank = LEVELS.index(wanted)

    try:
        with open(args.path, "r", encoding="utf-8") as stream:
            lines = stream.read().splitlines()
    except (OSError, UnicodeDecodeError):
        print(f"logscan.py: cannot open {args.path}", file=sys.stderr)
        sys.exit(1)

    count = 0
    for line in lines:
        fields = line.split()
        if len(fields) < 3:
            continue
        level = fields[2]
        if level not in LEVELS:
            continue
        rank = LEVELS.index(level)
        if args.at_least:
            matched = rank >= wanted_rank
        else:
            matched = rank == wanted_rank
        if not matched:
            continue
        count += 1
        if args.limit is None or count <= args.limit:
            print(line)

    print(f"count={count}", file=sys.stderr)
    sys.exit(0)


if __name__ == "__main__":
    main()
