import time
from collections import OrderedDict, defaultdict


class LRUCache:
    def __init__(self, capacity: int, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl is not None and not ttl > 0:
            raise ValueError("ttl must be greater than 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._data = OrderedDict()  # key -> [value, stored_at], LRU first
        self._keyed = defaultdict(set)  # key -> generation ids still present
        self._gen = 0
        self._expired = set()  # ids counted as expired
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _sweep(self):
        if self._ttl is None:
            return
        now = self._clock()
        ttl = self._ttl
        for key, entry in list(self._data.items()):
            value, stored_at = entry
            if now - stored_at >= ttl:
                self._data.pop(key, None)
                ids = self._keyed.get(key)
                if ids:
                    for ident in ids:
                        if ident not in self._expired:
                            self._expired.add(ident)
                            self._expirations += 1
                    self._keyed.pop(key, None)

    def _get_entry(self, key):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, stored_at = entry
        if self._ttl is not None and self._clock() - stored_at >= self._ttl:
            return None
        return entry

    def get(self, key, default=None):
        entry = self._get_entry(key)
        if entry is None:
            self._misses += 1
            return default
        self._data.move_to_end(key)
        self._hits += 1
        return entry[0]

    def put(self, key, value):
        self._sweep()
        evicted = None
        if self._get_entry(key) is not None:
            self._data.move_to_end(key)
        else:
            live = [k for k, (_, stored_at) in self._data.items()
                    if self._ttl is None or self._clock() - stored_at < self._ttl]
            if len(live) >= self._capacity:
                evicted = live[0]
                self._data.pop(evicted, None)
                ids = self._keyed.pop(evicted, None)
                if ids:
                    self._expired.update(ids)
                self._evictions += 1
        self._gen += 1
        ident = self._gen
        self._data[key] = [value, self._clock()]
        stale = self._keyed.get(key)
        if stale:
            self._expired.update(stale)
        self._keyed[key] = {ident}
        return evicted

    def __len__(self):
        self._sweep()
        return len(self._data)

    def __contains__(self, key):
        return self._get_entry(key) is not None

    def keys(self):
        self._sweep()
        return list(self._data.keys())

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self._sweep()
        self._capacity = capacity
        evicted = []
        while True:
            live = [k for k, (_, stored_at) in self._data.items()
                    if self._ttl is None or self._clock() - stored_at < self._ttl]
            if len(live) <= self._capacity:
                break
            key = live[0]
            self._data.pop(key, None)
            ids = self._keyed.pop(key, None)
            if ids:
                self._expired.update(ids)
            self._evictions += 1
            evicted.append(key)
        return evicted

    def stats(self):
        self._sweep()
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }
