"""Parser for a simple INI-style configuration format."""

__all__ = ["ParseError", "Config", "parse"]

_INT_CHARS = set("0123456789")
_TRUE_WORDS = {"true", "yes", "on", "1"}
_FALSE_WORDS = {"false", "no", "off", "0"}


class ParseError(ValueError):
    """Raised when the input text is not valid."""

    def __init__(self, lineno: int, message: str):
        self.lineno = lineno
        super().__init__(f"{message} (line {lineno})")


class Config:
    """An immutable mapping of sections to ordered key/value pairs."""

    def __init__(self):
        self._data = {}
        self._order = []

    def sections(self):
        return list(self._order)

    def keys(self, section):
        try:
            return list(self._data[section])
        except KeyError:
            raise KeyError(section) from None

    def get(self, section, key, default=None):
        sec = self._data.get(section)
        if sec is None:
            return default
        return sec.get(key, default)

    def getint(self, section, key, default=None):
        value = self.get(section, key, None)
        if value is None:
            return default
        text = value
        if text[:1] in ("+", "-"):
            text = text[1:]
        if not text or not set(text) <= _INT_CHARS:
            raise ValueError(f"not an integer: {value!r}")
        return int(value)

    def getbool(self, section, key, default=None):
        value = self.get(section, key, None)
        if value is None:
            return default
        lowered = value.lower()
        if lowered in _TRUE_WORDS:
            return True
        if lowered in _FALSE_WORDS:
            return False
        raise ValueError(f"not a boolean: {value!r}")

    def getlist(self, section, key, default=None):
        value = self.get(section, key, None)
        if value is None:
            return default
        return [item.strip() for item in value.split(",") if item.strip()]


def parse(text: str) -> Config:
    config = Config()
    current = None
    last_key = None
    prev_is_key = False

    for index, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        indented = line[:1] in (" ", "\t")

        if not stripped:
            prev_is_key = False
            last_key = None
            continue

        if stripped[0] in ";#":
            prev_is_key = False
            last_key = None
            continue

        if indented:
            if not prev_is_key or current is None or last_key is None:
                raise ParseError(index, "indented line is not a valid continuation")
            config._data[current][last_key] += "\n" + stripped
            continue

        prev_is_key = False
        last_key = None

        if stripped.startswith("["):
            if not stripped.endswith("]"):
                raise ParseError(index, "invalid section header")
            name = stripped[1:-1].strip()
            if not name:
                raise ParseError(index, "empty section name")
            if name in config._data:
                raise ParseError(index, f"duplicate section: {name!r}")
            config._data[name] = {}
            config._order.append(name)
            current = name
            continue

        if "=" not in stripped:
            raise ParseError(index, "invalid line")

        key, _, value = stripped.partition("=")
        key = key.strip()
        value = value.strip()
        if not key:
            raise ParseError(index, "empty key")
        if current is None:
            raise ParseError(index, "key before any section header")
        if key in config._data[current]:
            raise ParseError(index, f"duplicate key: {key!r}")
        config._data[current][key] = value
        last_key = key
        prev_is_key = True

    return config
