"""Parse INI-style configuration text."""

import re

__all__ = ["ParseError", "Config", "parse"]

_INT_RE = re.compile(r"^[+-]?[0-9]+$")
_TRUE = {"true", "yes", "on", "1"}
_FALSE = {"false", "no", "off", "0"}


class ParseError(ValueError):
    def __init__(self, lineno, message):
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")


class Config:
    def __init__(self):
        self._data = {}
        self._order = []

    def sections(self):
        return list(self._order)

    def keys(self, section):
        if section not in self._data:
            raise KeyError(section)
        return list(self._data[section].keys())

    def get(self, section, key, default=None):
        sec = self._data.get(section)
        if sec is None:
            return default
        return sec.get(key, default)

    def getint(self, section, key, default=None):
        value = self.get(section, key)
        if value is None:
            return default
        if not _INT_RE.match(value):
            raise ValueError(f"not an integer: {value!r}")
        return int(value)

    def getbool(self, section, key, default=None):
        value = self.get(section, key)
        if value is None:
            return default
        lowered = value.lower()
        if lowered in _TRUE:
            return True
        if lowered in _FALSE:
            return False
        raise ValueError(f"not a boolean: {value!r}")

    def getlist(self, section, key, default=None):
        value = self.get(section, key)
        if value is None:
            return default
        return [item for item in (p.strip() for p in value.split(",")) if item]


def parse(text):
    config = Config()
    current = None
    last_key = None
    pending = False

    for lineno, raw in enumerate(text.splitlines(), 1):
        stripped = raw.strip()
        is_indented = raw[:1] in (" ", "\t")
        is_blank = not stripped
        is_comment = stripped[:1] in (";", "#")
        was_pending = pending
        pending = False

        if is_blank or is_comment:
            continue

        if is_indented:
            if not (was_pending and current is not None and last_key is not None):
                raise ParseError(lineno, "unexpected indented line")
            config._data[current][last_key] += "\n" + stripped
            pending = True
            continue

        if stripped.startswith("["):
            if not stripped.endswith("]"):
                raise ParseError(lineno, "invalid section header")
            name = stripped[1:-1].strip()
            if not name:
                raise ParseError(lineno, "empty section name")
            if name in config._data:
                raise ParseError(lineno, f"duplicate section {name!r}")
            config._data[name] = {}
            config._order.append(name)
            current = name
            last_key = None
            continue

        if "=" not in stripped:
            raise ParseError(lineno, "invalid line")
        if current is None:
            raise ParseError(lineno, "key before any section header")
        key, _, value = stripped.partition("=")
        key = key.strip()
        value = value.strip()
        if not key:
            raise ParseError(lineno, "empty key")
        if key in config._data[current]:
            raise ParseError(lineno, f"duplicate key {key!r}")
        config._data[current][key] = value
        last_key = key
        pending = True

    return config
