"""Semantic Versioning 2.0.0 versions and simple version ranges."""

from __future__ import annotations

import re

__all__ = ["Version", "satisfies"]

_NUM = re.compile(r"^(0|[1-9]\d*)$")
_IDENT = re.compile(r"^[0-9A-Za-z-]+$")
_PARTIAL = re.compile(r"^(0|[1-9]\d*)(?:\.(0|[1-9]\d*))?(?:\.(0|[1-9]\d*))?$")


def _compare_prerelease(a: tuple[str, ...], b: tuple[str, ...]) -> int:
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        xn = _NUM.match(x)
        yn = _NUM.match(y)
        if xn and yn:
            ix, iy = int(x), int(y)
            if ix != iy:
                return -1 if ix < iy else 1
        elif xn:
            return -1
        elif yn:
            return 1
        elif x != y:
            return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


class Version:
    """An immutable Semantic Version 2.0.0 version number."""

    __slots__ = ("major", "minor", "patch", "prerelease", "build", "_hash")

    def __init__(
        self,
        major: int,
        minor: int,
        patch: int,
        prerelease: tuple[str, ...] = (),
        build: tuple[str, ...] = (),
    ) -> None:
        object.__setattr__(self, "major", major)
        object.__setattr__(self, "minor", minor)
        object.__setattr__(self, "patch", patch)
        object.__setattr__(self, "prerelease", tuple(prerelease))
        object.__setattr__(self, "build", tuple(build))
        object.__setattr__(self, "_hash", None)

    def __setattr__(self, name: str, value: object) -> None:
        raise AttributeError("Version objects are immutable")

    @staticmethod
    def _parse_number(text: str, part: str) -> int:
        if not _NUM.match(text):
            raise ValueError(f"invalid {part} number in version: {text!r}")
        return int(text)

    @staticmethod
    def _parse_identifiers(text: str, kind: str, allow_leading_zeros: bool) -> tuple[str, ...]:
        if text == "":
            raise ValueError(f"empty {kind} part in version")
        idents = text.split(".")
        for ident in idents:
            if ident == "":
                raise ValueError(f"empty {kind} identifier in version")
            if not _IDENT.match(ident):
                raise ValueError(f"invalid {kind} identifier {ident!r} in version")
            if (
                not allow_leading_zeros
                and _NUM.match(ident) is None
                and all('0' <= c <= '9' for c in ident)
                and len(ident) > 1
                and ident[0] == "0"
            ):
                raise ValueError(
                    f"numeric {kind} identifier {ident!r} has leading zeros"
                )
        return tuple(idents)

    @classmethod
    def parse(cls, text: str) -> "Version":
        if not isinstance(text, str):
            raise ValueError("version must be a string")
        rest = text
        build: tuple[str, ...] = ()
        prerelease: tuple[str, ...] = ()
        plus = rest.find("+")
        if plus != -1:
            build = cls._parse_identifiers(rest[plus + 1:], "build", True)
            rest = rest[:plus]
        dash = rest.find("-")
        if dash != -1:
            prerelease = cls._parse_identifiers(rest[dash + 1:], "prerelease", False)
            rest = rest[:dash]
        parts = rest.split(".")
        if len(parts) != 3:
            raise ValueError(f"invalid version: {text!r}")
        major = cls._parse_number(parts[0], "major")
        minor = cls._parse_number(parts[1], "minor")
        patch = cls._parse_number(parts[2], "patch")
        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text

    def __repr__(self) -> str:
        return f"Version({str(self)!r})"

    def _cmp(self, other: object) -> int:
        if not isinstance(other, Version):
            return NotImplemented
        left = (self.major, self.minor, self.patch)
        right = (other.major, other.minor, other.patch)
        if left != right:
            return -1 if left < right else 1
        return _compare_prerelease(self.prerelease, other.prerelease)

    def __lt__(self, other: object) -> bool:
        result = self._cmp(other)
        if result is NotImplemented:
            return result
        return result < 0

    def __le__(self, other: object) -> bool:
        result = self._cmp(other)
        if result is NotImplemented:
            return result
        return result <= 0

    def __gt__(self, other: object) -> bool:
        result = self._cmp(other)
        if result is NotImplemented:
            return result
        return result > 0

    def __ge__(self, other: object) -> bool:
        result = self._cmp(other)
        if result is NotImplemented:
            return result
        return result >= 0

    def __eq__(self, other: object) -> bool:
        result = self._cmp(other)
        if result is NotImplemented:
            return result
        return result == 0

    def __ne__(self, other: object) -> bool:
        result = self._cmp(other)
        if result is NotImplemented:
            return result
        return result != 0

    def __hash__(self) -> int:
        cached = self._hash
        if cached is None:
            cached = hash((self.major, self.minor, self.patch, self.prerelease))
            object.__setattr__(self, "_hash", cached)
        return cached

    def bump(self, kind: str) -> "Version":
        if kind == "major":
            return Version(self.major + 1, 0, 0)
        if kind == "minor":
            return Version(self.major, self.minor + 1, 0)
        if kind == "patch":
            return Version(self.major, self.minor, self.patch + 1)
        raise ValueError(f"invalid bump kind: {kind!r}")


def _parse_partial(text: str) -> tuple[Version, int]:
    match = _PARTIAL.match(text)
    if match is None:
        raise ValueError(f"invalid version in range: {text!r}")
    major = int(match.group(1))
    given = 1 + (match.group(2) is not None) + (match.group(3) is not None)
    minor = int(match.group(2)) if match.group(2) is not None else 0
    patch = int(match.group(3)) if match.group(3) is not None else 0
    return Version(major, minor, patch), given


def _caret_bounds(base: Version) -> tuple[Version, Version]:
    if base.major != 0:
        upper = Version(base.major + 1, 0, 0)
    elif base.minor != 0:
        upper = Version(0, base.minor + 1, 0)
    else:
        upper = Version(0, 0, base.patch + 1)
    return base, upper


def _tilde_bounds(base: Version, given: int) -> tuple[Version, Version]:
    if given == 1:
        upper = Version(base.major + 1, 0, 0)
    else:
        upper = Version(base.major, base.minor + 1, 0)
    return base, upper


def _comparators(spec: str) -> list[tuple[str, Version]]:
    comps: list[tuple[str, Version]] = []
    for token in spec.split():
        if token.startswith("^"):
            base, _given = _parse_partial(token[1:])
            lower, upper = _caret_bounds(base)
            comps.append((">=", lower))
            comps.append(("<", upper))
        elif token.startswith("~"):
            base, given = _parse_partial(token[1:])
            lower, upper = _tilde_bounds(base, given)
            comps.append((">=", lower))
            comps.append(("<", upper))
        else:
            for op in (">=", "<=", ">", "<", "="):
                if token.startswith(op):
                    operand = token[len(op):]
                    break
            else:
                op = "="
                operand = token
            if operand == "":
                raise ValueError(f"invalid comparator: {token!r}")
            version, _given = _parse_partial(operand)
            comps.append((op, version))
    return comps


def _test(op: str, version: Version, target: Version) -> bool:
    if op == ">=":
        return version >= target
    if op == ">":
        return version > target
    if op == "<=":
        return version <= target
    if op == "<":
        return version < target
    return version == target


def satisfies(version: "Version | str", spec: str) -> bool:
    if isinstance(version, str):
        version = Version.parse(version)
    elif not isinstance(version, Version):
        raise ValueError("version must be a Version or a string")
    if not isinstance(spec, str):
        raise ValueError("spec must be a string")
    comps = _comparators(spec)
    if not comps:
        raise ValueError("empty version range spec")
    return all(_test(op, version, target) for op, target in comps)
