```python
"""Semantic Versioning 2.0.0 parsing, comparison and simple ranges."""

import re
from functools import total_ordering

_NUM = r"0|[1-9]\d*"
_PRE_ID = r"(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)"
_BUILD_ID = r"[0-9A-Za-z-]+"

_VERSION_RE = re.compile(
    rf"^({_NUM})\.({_NUM})\.({_NUM})"
    rf"(?:-({_PRE_ID}(?:\.{_PRE_ID})*))?"
    rf"(?:\+({_BUILD_ID}(?:\.{_BUILD_ID})*))?$"
)

_PARTIAL_RE = re.compile(
    rf"^({_NUM})(?:\.({_NUM})(?:\.({_NUM}))?)?"
    rf"(?:-({_PRE_ID}(?:\.{_PRE_ID})*))?"
    rf"(?:\+({_BUILD_ID}(?:\.{_BUILD_ID})*))?$"
)

_COMPARATOR_RE = re.compile(
    r"^(?P<op>\^|~|>=|<=|>|<|=)?(?P<num>\d+(?:\.\d+)?(?:\.\d+)?)"
    r"(?P<pre>-[0-9A-Za-z.-]+)?(?P<build>\+[0-9A-Za-z.-]+)?$"
)


def _ident_key(ident):
    if ident.isdigit():
        return (0, int(ident), "")
    return (1, 0, ident)


def _compare_pre(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    n = min(len(a), len(b))
    for i in range(n):
        ka, kb = _ident_key(a[i]), _ident_key(b[i])
        if ka != kb:
            return -1 if ka < kb else 1
    if len(a) == len(b):
        return 0
    return -1 if len(a) < len(b) else 1


@total_ordering
class Version:
    __slots__ = ("major", "minor", "patch", "prerelease", "build")

    def __init__(self, major, minor, patch, prerelease=(), build=()):
        object.__setattr__(self, "major", major)
        object.__setattr__(self, "minor", minor)
        object.__setattr__(self, "patch", patch)
        object.__setattr__(self, "prerelease", tuple(prerelease))
        object.__setattr__(self, "build", tuple(build))

    def __setattr__(self, name, value):
        raise AttributeError("Version is immutable")

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise ValueError("version must be a string")
        m = _VERSION_RE.match(text)
        if m is None:
            raise ValueError(f"invalid semantic version: {text!r}")
        major, minor, patch, pre, build = m.groups()
        prerelease = tuple(pre.split(".")) if pre else ()
        build_ids = tuple(build.split(".")) if build else ()
        return cls(int(major), int(minor), int(patch), prerelease, build_ids)

    def _key(self):
        return (self.major, self.minor, self.patch, self.prerelease)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() == other._key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        base = (self.major, self.minor, self.patch)
        other_base = (other.major, other.minor, other.patch)
        if base != other_base:
            return base < other_base
        return _compare_pre(self.prerelease, other.prerelease) < 0

    def __hash__(self):
        return hash(self._key())

    def __str__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(self.prerelease)
        if self.build:
            s += "+" + ".".join(self.build)
        return s

    def __repr__(self):
        return f"Version({str(self)!r})"

    def bump(self, kind):
        if kind == "major":
            return Version(self.major + 1, 0, 0)
        if kind == "minor":
            return Version(self.major, self.minor + 1, 0)
        if kind == "patch":
            return Version(self.major, self.minor, self.patch + 1)
        raise ValueError(f"invalid bump kind: {kind!r}")


def _parse_partial(text):
    m = _PARTIAL_RE.match(text)
    if m is None:
        raise ValueError(f"invalid version in range: {text!r}")
    major, minor, patch, pre, build = m.groups()
    if pre is not None or build is not None:
        raise ValueError(f"partial version may not have pre-release or build: {text!r}")
    parts = (major, minor, patch)
    nums = tuple(int(p) if p is not None else 0 for p in parts)
    provided = sum(1 for p in parts if p is not None)
    return Version(*nums), provided


def _cmp_comparator(op, bound, provided=3):
    if op == ">=":
        if provided < 3:
            return lambda v: (v.major, v.minor, v.patch) >= (bound.major, bound.minor, bound.patch)
        return lambda v: v >= bound
    if op == ">":
        return lambda v: v > bound
    if op == "<=":
        if provided < 3:
            return lambda v: (v.major, v.minor, v.patch) <= (bound.major, bound.minor, bound.patch)
        return lambda v: v <= bound
    if op == "<":
        return lambda v: v < bound
    return lambda v: v == bound


def _caret_comparator(bound, provided):
    lower = lambda v: v >= bound
    if bound.major != 0:
        upper_v = Version(bound.major + 1, 0, 0)
    elif provided == 1:
        upper_v = Version(1, 0, 0)
    elif bound.minor != 0:
        upper_v = Version(0, bound.minor + 1, 0)
    elif provided == 2:
        upper_v = Version(0, 1, 0)
    else:
        upper_v = Version(0, 0, bound.patch + 1)
    upper = lambda v: v < upper_v
    return lambda v: lower(v) and upper(v)


def _tilde_comparator(bound, provided):
    lower = lambda v: v >= bound
    if provided == 1:
        upper_v = Version(bound.major + 1, 0, 0)
    else:
        upper_v = Version(bound.major, bound.minor + 1, 0)
    upper = lambda v: v < upper_v
    return lambda v: lower(v) and upper(v)


def _parse_comparator(token):
    m = _COMPARATOR_RE.match(token)
    if m is None:
        raise ValueError(f"invalid comparator: {token!r}")
    op = m.group("op")
    version_text = m.group("num") + (m.group("pre") or "") + (m.group("build") or "")
    if op is None or op == "=":
        if "-" in version_text or "+" in version_text:
            raise ValueError(f"invalid comparator: {token!r}")
        bound = Version.parse(version_text)
        return _cmp_comparator("=", bound)
    bound, provided = _parse_partial(version_text)
    if op == "^":
        return _caret_comparator(bound, provided)
    if op == "~":
        return _tilde_comparator(bound, provided)
    return _cmp_comparator(op, bound, provided)


def satisfies(version, spec):
    if isinstance(version, str):
        version = Version.parse(version)
    if not isinstance(spec, str) or not spec.strip():
        raise ValueError("spec must be a non-empty string")
    checks = [_parse_comparator(token) for token in spec.split()]
    return all(check(version) for check in checks)
