"""Business-day arithmetic on datetime.date values.

A business day is a date whose weekday is not in ``weekend`` and that is not
in ``holidays``. All functions accept ``holidays`` and ``weekend`` as keyword
arguments.
"""

from datetime import date, timedelta

__all__ = ["is_business_day", "business_days_between", "add_business_days"]


def _validate(weekend):
    weekend = frozenset(weekend)
    for wd in weekend:
        if not isinstance(wd, int) or isinstance(wd, bool) or not 0 <= wd <= 6:
            raise ValueError(
                "weekend entries must be integers from 0 to 6, got %r" % (wd,)
            )
    if len(weekend) >= 7:
        raise ValueError("at least one weekday must remain a working day")
    return weekend


def is_business_day(d, *, holidays=(), weekend=(5, 6)):
    """Return True if ``d`` is a business day."""
    weekend = _validate(weekend)
    if d.weekday() in weekend:
        return False
    return d not in set(holidays)


def business_days_between(start, end, *, include_start=True, include_end=False,
                          holidays=(), weekend=(5, 6)):
    """Count business days from ``start`` to ``end``.

    ``start`` is counted only if ``include_start`` is true and ``end`` only if
    ``include_end`` is true. With the defaults the range is half-open.
    """
    weekend = _validate(weekend)
    if start > end:
        raise ValueError("start must not be after end")
    holiday_set = set(holidays)
    if start == end:
        if include_start and include_end:
            wd = start.weekday()
            return 1 if (wd not in weekend and start not in holiday_set) else 0
        return 0

    def count_upto(d):
        """Business days from ``start`` through ``d`` (inclusive)."""
        wd = d.weekday()
        full_weeks, rem = divmod((d - start).days + 1, 7)
        workdays_per_week = 7 - len(weekend)
        n = full_weeks * workdays_per_week
        for i in range(rem):
            if (start + timedelta(days=i)).weekday() not in weekend:
                n += 1
        return n - sum(
            1 for h in holiday_set
            if start <= h <= d and h.weekday() not in weekend
        )

    total = count_upto(end)
    if not include_end:
        total -= 1 if is_business_day(end, holidays=holiday_set, weekend=weekend) else 0
    if not include_start:
        total -= 1 if is_business_day(start, holidays=holiday_set, weekend=weekend) else 0
    return total


def add_business_days(d, n, *, holidays=(), weekend=(5, 6)):
    """Return the n-th business day after (n > 0) or before (n < 0) ``d``.

    ``d`` itself is never counted as one of the n days. For ``n == 0``,
    return ``d`` if it is a business day, otherwise the first business day
    after ``d``.
    """
    weekend = _validate(weekend)
    holiday_set = set(holidays)

    def is_bd(x):
        return x.weekday() not in weekend and x not in holiday_set

    step = 1 if n >= 0 else -1
    cur = d
    if n == 0:
        while not is_bd(cur):
            cur += timedelta(days=step)
        return cur
    remaining = abs(n)
    while remaining > 0:
        cur += timedelta(days=step)
        if is_bd(cur):
            remaining -= 1
    return cur
