"""Token-bucket rate limiter."""

import time

__all__ = ["TokenBucket"]


class TokenBucket:
    """A token-bucket rate limiter driven by an injectable clock."""

    def __init__(self, rate, capacity, clock=time.monotonic):
        if not (isinstance(rate, (int, float)) and rate > 0):
            raise ValueError("rate must be a number greater than 0")
        if not (isinstance(capacity, (int, float)) and capacity > 0):
            raise ValueError("capacity must be a number greater than 0")
        self._rate = rate
        self._capacity = capacity
        self._clock = clock
        self._tokens = capacity
        self._last = clock()

    def _check_n(self, n):
        if not (isinstance(n, (int, float)) and n > 0):
            raise ValueError("n must be greater than 0")
        if n > self._capacity:
            raise ValueError("n must be at most capacity")

    def _refill(self):
        now = self._clock()
        if now > self._last:
            self._tokens = min(
                self._capacity, self._tokens + (now - self._last) * self._rate
            )
            self._last = now

    def try_acquire(self, n=1):
        self._check_n(n)
        self._refill()
        if self._tokens >= n:
            self._tokens -= n
            return True
        return False

    def wait_time(self, n=1):
        self._check_n(n)
        self._refill()
        if self._tokens >= n:
            return 0.0
        return (n - self._tokens) / self._rate

    def available(self):
        self._refill()
        return self._tokens
