from array import array
from itertools import product


def _lcs_table(a: list[str], b: list[str]) -> list[array]:
    """Suffix-LCS lengths: ``table[i][j] == len(LCS(a[i:], b[j:]))``.

    Rows are ``array('i')`` so the ``(len(a)+1) x (len(b)+1)`` table holds no
    per-cell Python objects.
    """
    n, m = len(a), len(b)
    table = [array("i", bytes(4 * (m + 1))) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        cur, nxt = table[i], table[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                cur[j] = nxt[j + 1] + 1
            else:
                x, y = nxt[j], cur[j + 1]
                cur[j] = x if x >= y else y
    return table


def diff(a: list[str], b: list[str]) -> list[str]:
    """Minimal line diff as an edit script with ``' '``/``'-'``/``'+'`` prefixes."""
    n, m = len(a), len(b)
    out: list[str] = []
    append = out.append
    table = _lcs_table(a, b)
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            append(" " + a[i])
            i += 1
            j += 1
        elif table[i + 1][j] >= table[i][j + 1]:
            append("-" + a[i])
            i += 1
        else:
            append("+" + b[j])
            j += 1
    if i < n:
        out.extend("-" + line for line in a[i:])
    if j < m:
        out.extend("+" + line for line in b[j:])
    return out


def _main() -> None:
    assert diff(["a", "b", "c"], ["a", "x", "c", "d"]) == [" a", "-b", "+x", " c", "+d"]
    for n in range(4):
        for m in range(4):
            for ta in product("ab", repeat=n):
                for tb in product("ab", repeat=m):
                    x, y = list(ta), list(tb)
                    s = diff(x, y)
                    assert [e[1:] for e in s if e[0] in " -"] == x
                    assert [e[1:] for e in s if e[0] in " +"] == y
                    assert sum(e[0] == " " for e in s) == _lcs_table(x, y)[0][0]
    print("ok")


if __name__ == "__main__":
    _main()
