"""Trie-backed autocomplete with case-insensitive matching and weighted suggestions."""

from __future__ import annotations


class _Node:
    __slots__ = ("children", "word", "weight")

    def __init__(self) -> None:
        self.children: dict[str, _Node] = {}
        self.word: str | None = None
        self.weight: float = 0.0


class Autocomplete:
    def __init__(self) -> None:
        self._root = _Node()
        self._count = 0

    def add(self, word: str, weight: float = 1) -> None:
        if not word:
            raise ValueError("word must be non-empty")
        key = word.casefold()
        node = self._root
        for ch in key:
            node = node.children.setdefault(ch, _Node())
        if node.word is None:
            self._count += 1
        node.word = word
        node.weight = weight

    def delete(self, word: str) -> bool:
        key = word.casefold()
        path: list[tuple[_Node, str]] = []
        node = self._root
        for ch in key:
            child = node.children.get(ch)
            if child is None:
                return False
            path.append((node, ch))
            node = child
        if node.word is None:
            return False
        node.word = None
        self._count -= 1
        for parent, ch in reversed(path):
            child = parent.children[ch]
            if child.children or child.word is not None:
                break
            del parent.children[ch]
        return True

    def complete(self, prefix: str, k: int = 10) -> list[str]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        node = self._root
        for ch in prefix.casefold():
            node = node.children.get(ch)
            if node is None:
                return []
        results: list[tuple[float, str, str]] = []
        stack = [node]
        while stack:
            cur = stack.pop()
            if cur.word is not None:
                results.append((-cur.weight, cur.word.casefold(), cur.word))
            stack.extend(cur.children.values())
        results.sort()
        return [word for _, _, word in results[:k]]

    def __contains__(self, word: str) -> bool:
        node = self._root
        for ch in word.casefold():
            node = node.children.get(ch)
            if node is None:
                return False
        return node.word is not None

    def __len__(self) -> int:
        return self._count
