"""Binary-search utilities: all operations run in O(log n) time."""


def _lower_bound(a, x):
    """Smallest i in [0, len(a)] such that a[i] >= x (len(a) if none)."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def _upper_bound(a, x):
    """Smallest i in [0, len(a)] such that a[i] > x (len(a) if none)."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def _bound_in(a, x, lo, hi, upper):
    """Lower (or upper) bound of x restricted to a[lo:hi]."""
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if (a[mid] <= x) if upper else (a[mid] < x):
            lo = mid + 1
        else:
            hi = mid
    return lo


def insertion_point(a, x):
    """Smallest index where x can be inserted, before any equal elements."""
    return _lower_bound(a, x)


def first_index(a, x):
    """Index of the first occurrence of x, or -1 if x is absent."""
    i = _lower_bound(a, x)
    if i < len(a) and a[i] == x:
        return i
    return -1


def last_index(a, x):
    """Index of the last occurrence of x, or -1 if x is absent."""
    i = _upper_bound(a, x) - 1
    if i >= 0 and a[i] == x:
        return i
    return -1


def count(a, x):
    """Number of elements equal to x."""
    return _upper_bound(a, x) - _lower_bound(a, x)


def rotation_offset(a):
    """Index of the minimum element of a rotated sorted (distinct) list."""
    if not a:
        raise ValueError("empty list has no rotation offset")
    if len(a) == 1 or a[0] < a[-1]:
        return 0
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] > a[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def search_rotated(a, x):
    """Index of x in a rotated sorted list of distinct values, or -1."""
    n = len(a)
    if n == 0:
        return -1
    off = rotation_offset(a)
    if x >= a[0]:
        i = _bound_in(a, x, 0, off + 1, False)
        if i <= off and a[i] == x:
            return i
    else:
        i = _bound_in(a, x, off + 1, n, False)
        if i < n and a[i] == x:
            return i
    return -1


def isqrt(n):
    """Largest integer r with r*r <= n, exact for arbitrarily large ints."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("isqrt() argument must be nonnegative")
    if n == 0:
        return 0
    # Integer Newton iteration r' = (r + n // r) // 2 started from an
    # over-estimate; the sequence decreases and lands exactly on the answer.
    r = 1 << (n.bit_length() + 1 >> 1)
    while True:
        s = (r + n // r) >> 1
        if s >= r:
            return r
        r = s
