"""Binary-search utilities.

Every function here runs in O(log n) comparisons (O(log n) iterations for
``isqrt``) and never modifies its arguments. Only the Python standard library
is used; the ``bisect`` and ``math.isqrt`` helpers are deliberately avoided.
"""


def _lower_bound(a, x):
    """Smallest i such that a[i] >= x, or len(a) if every element is < x.

    Strictly O(log n) comparisons: the window [lo, hi] always contains the
    answer and shrinks by at least one element per iteration, so the loop
    runs at most ceil(log2(n + 1)) times for a list of length n.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo


def first_index(a, x):
    """Index of the first element of `a` equal to `x`, or -1 if there is none.

    `a` must be sorted in non-decreasing order.
    """
    i = _lower_bound(a, x)
    if i < len(a) and a[i] == x:
        return i
    return -1


def last_index(a, x):
    """Index of the last element of `a` equal to `x`, or -1 if there is none.

    `a` must be sorted in non-decreasing order.
    """
    i = _lower_bound(a, x + 1) - 1
    if i >= 0 and a[i] == x:
        return i
    return -1


def insertion_point(a, x):
    """Smallest index before which `x` can be inserted keeping `a` sorted.

    `x` lands before any elements equal to it; returns len(a) when `x` is
    greater than every element.
    """
    return _lower_bound(a, x)


def count(a, x):
    """Number of elements of `a` equal to `x` (two binary searches)."""
    lo = _lower_bound(a, x)
    hi = _lower_bound(a, x + 1)
    return hi - lo


def rotation_offset(a):
    """Index of the smallest element of a rotated sorted list of distinct values.

    Returns 0 for a list that is not rotated. Raises ValueError if `a` is
    empty. Each iteration performs exactly two element comparisons and
    shrinks the window [lo, hi] by about half, so the loop runs at most
    ceil(log2 n) times: O(log n) comparisons in total.
    """
    if not a:
        raise ValueError("empty list has no rotation offset")
    n = len(a)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[lo] <= a[mid]:
            if a[mid] <= a[hi]:
                return lo  # [lo..hi] is fully sorted; a[lo] is its minimum
            lo = mid + 1
        else:
            hi = mid
    return lo


def search_rotated(a, x):
    """Index of `x` in a rotated sorted list of distinct values, or -1.

    At most two binary-search passes, hence O(log n) comparisons.
    """
    n = len(a)
    if n == 0:
        return -1
    pivot = rotation_offset(a)
    if n == 1:
        return 0 if a[0] == x else -1
    if x == a[pivot]:
        return pivot
    last = a[n - 1]
    if x > last:
        lo, hi = 0, pivot - 1
    else:
        lo, hi = pivot + 1, n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        v = a[mid]
        if v == x:
            return mid
        if v < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def isqrt(n):
    """Largest integer r with r * r <= n, exact for arbitrarily large ints.

    Raises TypeError if `n` is not an int (bool counts as not an int) and
    ValueError if `n` is negative. The Newton iteration halves the number of
    correct digits per step and stops as soon as the sequence stops
    decreasing, which takes O(log n) iterations in the worst case. The final
    correction loop runs at most once (the iterate never undershoots).
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("isqrt() argument must be an int, not "
                        f"{type(n).__name__}")
    if n < 0:
        raise ValueError("isqrt() argument must be nonnegative")
    if n < 2:
        return n
    x = 1 << ((n.bit_length() + 1) >> 1)
    while True:
        y = (x + n // x) >> 1
        if y >= x:
            break
        x = y
    if x * x > n:
        x -= 1
    return x
