class CountingSeq:
    """Immutable sequence that counts element accesses and comparisons."""

    def __init__(self, data):
        self._data = list(data)
        self.count = 0

    def __len__(self):
        return len(self._data)

    def __getitem__(self, i):
        self.count += 1
        return self._data[i]

    def __iter__(self):
        raise AssertionError("sequence must not be iterated")

    def __contains__(self, item):
        raise AssertionError("sequence must not use `in`")

    def __eq__(self, other):
        raise AssertionError("sequence must not be compared as a whole")

    def __hash__(self):
        return object.__hash__(self)



