"""A small synchronous event emitter."""

from __future__ import annotations

from typing import Any, Callable, Hashable

_ORIGINATOR = "_event_listener_originator"


class EmitError(Exception):
    """Raised when one or more listeners raised during an ``emit``.

    Attributes:
        errors: ``(listener, exception)`` pairs in the order the listeners
            were called.
    """

    def __init__(self, errors: list[tuple[Callable[..., Any], BaseException]]):
        super().__init__(f"{len(errors)} listener(s) failed")
        self.errors = errors


class Emitter:
    def __init__(self) -> None:
        # event -> registrations in order; each registration is the callable
        # stored for the listener (the listener itself for ``on``, a one-shot
        # wrapper for ``once``).
        self._registry: dict[Hashable, list[Callable[..., Any]]] = {}

    def on(self, event: Hashable, listener: Callable[..., Any]) -> Callable[..., Any]:
        self._registry.setdefault(event, []).append(listener)
        return listener

    def once(self, event: Hashable, listener: Callable[..., Any]) -> Callable[..., Any]:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            # Removed just before the first call, so the listener runs at
            # most once even if it re-emits the same event from inside.
            self._remove_first(event, wrapper)
            return listener(*args, **kwargs)

        setattr(wrapper, _ORIGINATOR, listener)
        self._registry.setdefault(event, []).append(wrapper)
        return wrapper

    @staticmethod
    def _origin(entry: Callable[..., Any]) -> Callable[..., Any]:
        return getattr(entry, _ORIGINATOR, entry)

    @staticmethod
    def _matches(entry: Callable[..., Any], listener: Callable[..., Any]) -> bool:
        return entry is listener or Emitter._origin(entry) is listener

    def _remove_first(self, event: Hashable, listener: Callable[..., Any]) -> int:
        entries = self._registry.get(event)
        if not entries:
            return 0
        for index, entry in enumerate(entries):
            if self._matches(entry, listener):
                del entries[index]
                if not entries:
                    del self._registry[event]
                return 1
        return 0

    def off(self, event: Hashable, listener: Callable[..., Any] | None = None) -> int:
        if listener is None:
            return len(self._registry.pop(event, ()))
        return self._remove_first(event, listener)

    def emit(self, event: Hashable, *args: Any, **kwargs: Any) -> int:
        entries = self._registry.get(event)
        if not entries:
            return 0
        # The set of listeners is fixed when emit starts: iterate a snapshot,
        # but skip registrations that were removed before their turn came.
        calls = 0
        errors: list[tuple[Callable[..., Any], BaseException]] = []
        for entry in list(entries):
            if entry not in entries:
                continue
            calls += 1
            try:
                entry(*args, **kwargs)
            except Exception as exc:
                errors.append((self._origin(entry), exc))
        if errors:
            raise EmitError(errors)
        return calls

    def listeners(self, event: Hashable) -> list[Callable[..., Any]]:
        return [self._origin(entry) for entry in self._registry.get(event, ())]
