"""Exact money arithmetic in cents using decimal.Decimal."""

from decimal import Decimal, ROUND_HALF_EVEN, InvalidOperation
from typing import Union

Number = Union[int, Decimal, str]

_TWO_PLACES = Decimal('0.01')


def to_cents(x: Number) -> Decimal:
    """Convert x to a Decimal rounded to 2 places with banker's rounding."""
    if isinstance(x, bool):
        raise TypeError(f"unsupported type: {type(x).__name__}")
    if isinstance(x, int):
        value = Decimal(x)
    elif isinstance(x, Decimal):
        value = x
    elif isinstance(x, str):
        try:
            value = Decimal(x.strip())
        except InvalidOperation:
            raise ValueError(f"not a finite decimal number: {x!r}") from None
    else:
        raise TypeError(f"unsupported type: {type(x).__name__}")

    if not value.is_finite():
        raise ValueError(f"not a finite decimal number: {x!r}")

    return value.quantize(_TWO_PLACES, rounding=ROUND_HALF_EVEN)


def allocate(amount: Number, ratios: list) -> list[Decimal]:
    """Split amount into parts proportional to ratios using largest-remainder."""
    if not isinstance(ratios, (list, tuple)) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")

    for r in ratios:
        if isinstance(r, bool) or not isinstance(r, (int, Decimal)):
            raise ValueError("ratios must be non-negative ints or Decimals")
        if r < 0:
            raise ValueError("ratios must be non-negative ints or Decimals")

    total_ratio = sum(ratios)
    if total_ratio <= 0:
        raise ValueError("sum of ratios must be positive")

    cents_amount = to_cents(amount)
    negative = cents_amount < 0
    work = -cents_amount if negative else cents_amount

    total_cents = int(work * 100)

    exact_shares = [Decimal(total_cents) * r / total_ratio for r in ratios]
    floored = [int(s) for s in exact_shares]
    remainders = [exact_shares[i] - floored[i] for i in range(len(ratios))]

    leftover = total_cents - sum(floored)

    order = sorted(
        range(len(ratios)),
        key=lambda i: (-remainders[i], i),
    )
    for i in range(leftover):
        floored[order[i]] += 1

    parts = []
    for c in floored:
        d = Decimal(c).scaleb(-2).quantize(_TWO_PLACES, rounding=ROUND_HALF_EVEN)
        parts.append(-d if negative else d)

    return parts


def split_even(amount: Number, n: int) -> list[Decimal]:
    """Split amount evenly into n parts."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer >= 1")
    if n < 1:
        raise ValueError("n must be >= 1")
    return allocate(amount, [1] * n)


def format_money(amount: Number) -> str:
    """Format amount as comma-separated string with 2 decimals."""
    value = to_cents(amount)
    negative = value < 0
    value = abs(value)
    value = value.quantize(_TWO_PLACES, rounding=ROUND_HALF_EVEN)

    if value == 0:
        negative = False

    units = int(value * 100)
    whole = units // 100
    frac = units % 100

    whole_str = f"{whole:,}"
    result = f"{whole_str}.{frac:02d}"
    if negative:
        result = f"-{result}"
    return result
