"""Exact money arithmetic in cents using decimal.Decimal."""

from decimal import Decimal, ROUND_HALF_EVEN, InvalidOperation, localcontext
import re

_CENT = Decimal("0.01")

_DECIMAL_RE = re.compile(r"[+-]?(\d+(\.\d*)?|\.\d+)$")


def _quantize_cent(value):
    with localcontext() as ctx:
        ctx.prec = max(len(value.as_tuple().digits), 1) + 16
        return value.quantize(_CENT, rounding=ROUND_HALF_EVEN)


def to_cents(x):
    if isinstance(x, bool):
        raise TypeError("bool is not an accepted amount type")
    if isinstance(x, float):
        raise TypeError("float is not an accepted amount type")
    if isinstance(x, int):
        value = Decimal(x)
    elif isinstance(x, Decimal):
        value = x
    elif isinstance(x, str):
        text = x.strip()
        if not _DECIMAL_RE.fullmatch(text):
            raise ValueError("not a finite decimal number")
        try:
            value = Decimal(text)
        except InvalidOperation:
            raise ValueError("not a finite decimal number") from None
    else:
        raise TypeError("unsupported amount type")
    if not value.is_finite():
        raise ValueError("not a finite decimal number")
    return _quantize_cent(value)


def allocate(amount, ratios):
    with localcontext() as ctx:
        ctx.prec = 2000
        if not ratios:
            raise ValueError("ratios must be a non-empty sequence")
        normalized = []
        weight_sum = Decimal(0)
        for r in ratios:
            if isinstance(r, bool) or not isinstance(r, (int, Decimal)):
                raise ValueError("ratios must be non-negative ints or Decimals")
            value = Decimal(r)
            if not value.is_finite() or value < 0:
                raise ValueError("ratios must be non-negative ints or Decimals")
            normalized.append(value)
            weight_sum += value
        if weight_sum <= 0:
            raise ValueError("sum of ratios must be positive")

        total = to_cents(amount)
        negative = total < 0
        cents = int(_quantize_cent(abs(total)) * 100)

        shares = [Decimal(cents) * r / weight_sum for r in normalized]
        bases = [int(s) for s in shares]
        remainders = [shares[i] - bases[i] for i in range(len(shares))]
        leftover = cents - sum(bases)
        order = sorted(range(len(shares)), key=lambda i: (-remainders[i], i))
        for i in order[:leftover]:
            bases[i] += 1

        if negative:
            bases = [-b for b in bases]
        return [_quantize_cent(Decimal(b) / 100) for b in bases]


def split_even(amount, n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be a positive integer")
    return allocate(amount, [1] * n)


def format_money(amount):
    value = to_cents(amount)
    sign = "-" if value < 0 else ""
    whole, frac = str(_quantize_cent(value)).split(".")
    if whole.startswith("-"):
        whole = whole[1:]
    grouped = ""
    for i, ch in enumerate(reversed(whole)):
        if i and i % 3 == 0:
            grouped = "," + grouped
        grouped = ch + grouped
    return f"{sign}{grouped}.{frac}"
