```python
"""A small finite-state-machine library."""

from dataclasses import dataclass, field
from typing import Any, Callable, Optional, Sequence, Union

__all__ = [
    "MachineError",
    "InvalidTransition",
    "GuardRejected",
    "State",
    "Transition",
    "Event",
    "Machine",
]


class MachineError(Exception):
    """Base class for all machine errors."""


class InvalidTransition(MachineError):
    """No transition for the event leaves the current state."""

    def __init__(self, state: str, event: str) -> None:
        super().__init__(
            f"no transition for event {event!r} from state {state!r}"
        )
        self.state = state
        self.event = event


class GuardRejected(MachineError):
    """Every transition for the event from the current state was rejected."""

    def __init__(self, state: str, event: str) -> None:
        super().__init__(
            f"every transition for event {event!r} from state {state!r} "
            "was rejected by its guard"
        )
        self.state = state
        self.event = event


@dataclass
class State:
    name: str
    on_enter: Optional[Callable[..., Any]] = None
    on_exit: Optional[Callable[..., Any]] = None


@dataclass
class Transition:
    event: str
    source: Union[str, Sequence[str]]
    target: Optional[str]
    guard: Optional[Callable[..., Any]] = None
    action: Optional[Callable[..., Any]] = None


@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict = field(default_factory=dict)


class Machine:
    def __init__(
        self,
        states: Sequence[Union[State, str]],
        transitions: Sequence[Transition],
        initial: str,
        context: Any = None,
    ) -> None:
        self._states: dict[str, State] = {}
        for item in states:
            state = State(item) if isinstance(item, str) else item
            if state.name in self._states:
                raise ValueError(f"duplicate state name {state.name!r}")
            self._states[state.name] = state
        if not self._states:
            raise ValueError("at least one state is required")
        if initial not in self._states:
            raise ValueError(f"initial state {initial!r} is not a known state")
        all_names = set(self._states)
        for transition in transitions:
            if transition.source == "*":
                sources: list[str] = list(all_names)
            elif isinstance(transition.source, (list, tuple)):
                sources = list(transition.source)
            else:
                sources = [transition.source]
            for name in sources:
                if name not in self._states:
                    raise ValueError(
                        f"transition for event {transition.event!r} names "
                        f"unknown source state {name!r}"
                    )
            if transition.target is not None and transition.target not in self._states:
                raise ValueError(
                    f"transition for event {transition.event!r} names "
                    f"unknown target state {transition.target!r}"
                )
        self._transitions: list[Transition] = list(transitions)
        self.initial = initial
        self.state = initial
        self.context = context
        self.history: list[tuple[str, str, str]] = []
        self._listeners: list[Callable[[str, Event, str], Any]] = []
        self._firing = False

    def _matches(self, transition: Transition) -> bool:
        source = transition.source
        if source == "*":
            return True
        if isinstance(source, (list, tuple)):
            return self.state in source
        return source == self.state

    def _candidates(self, event: str) -> list[Transition]:
        return [
            t
            for t in self._transitions
            if t.event == event and self._matches(t)
        ]

    @staticmethod
    def _target_of(transition: Transition, current: str) -> str:
        return current if transition.target is None else transition.target

    def fire(self, event: str, **data: Any) -> str:
        if self._firing:
            raise MachineError(
                f"cannot fire event {event!r} while another event is being processed"
            )
        candidates = self._candidates(event)
        if not candidates:
            raise InvalidTransition(self.state, event)
        shared: dict = data
        current = self.state
        self._firing = True
        try:
            chosen = None
            for candidate in candidates:
                target = self._target_of(candidate, current)
                if candidate.guard is None or candidate.guard(
                    self, Event(event, current, target, shared)
                ):
                    chosen = candidate
                    break
            if chosen is None:
                raise GuardRejected(current, event)
            target = self._target_of(chosen, current)
            hook_event = Event(event, current, target, shared)
            if chosen.target is None:
                if chosen.action is not None:
                    chosen.action(self, hook_event)
                self.history.append((current, event, current))
            else:
                source_state = self._states[current]
                if source_state.on_exit is not None:
                    source_state.on_exit(self, hook_event)
                if chosen.action is not None:
                    chosen.action(self, hook_event)
                self.state = target
                self.history.append((current, event, target))
                target_state = self._states[target]
                if target_state.on_enter is not None:
                    target_state.on_enter(self, hook_event)
            for listener in list(self._listeners):
                listener(current, hook_event, target)
            return self.state
        finally:
            self._firing = False

    def can_fire(self, event: str, **data: Any) -> bool:
        candidates = self._candidates(event)
        if not candidates:
            return False
        shared: dict = data
        current = self.state
        for candidate in candidates:
            if candidate.guard is None:
                return True
            target = self._target_of(candidate, current)
            if candidate.guard(self, Event(event, current, target, shared)):
                return True
        return False

    def available_events(self) -> list[str]:
        names = {t.event for t in self._transitions if self._matches(t)}
        return sorted(names)

    def on_transition(self, listener: Callable[[str, Event, str], Any]) -> None:
        self._listeners.append(listener)

    def reset(self) -> None:
        self.state = self.initial
        self.history.clear()
