```python
"""A vending machine built on the `fsm` package."""

from fsm import InvalidTransition, Machine, State, Transition

__all__ = [
    "VendingMachine",
    "VendingError",
    "SoldOut",
    "InsufficientCredit",
]

COINS = (5, 10, 25, 100)


class VendingError(Exception):
    """Base class for vending machine errors."""


class SoldOut(VendingError):
    """The product has no stock left."""


class InsufficientCredit(VendingError):
    """Not enough credit has been inserted for the product."""


def _payout(amount: int) -> list[int]:
    """Greedy change from the largest coin down, in descending order."""
    coins: list[int] = []
    for coin in sorted(COINS, reverse=True):
        while amount >= coin:
            coins.append(coin)
            amount -= coin
    return coins


class VendingMachine:
    def __init__(self, products: dict[str, tuple[int, int]]) -> None:
        self._prices: dict[str, int] = {}
        self._stock: dict[str, int] = {}
        for code, (price, stock) in products.items():
            self._prices[code] = int(price)
            self._stock[code] = int(stock)
        self._credit = 0
        self._sold: dict[str, int] = {}
        self._revenue = 0
        self._change: list[int] = []

        states = [
            State("idle"),
            State("credit"),
            State("maintenance"),
        ]
        transitions = [
            Transition("insert", ["idle", "credit"], "credit",
                       action=self._action_insert),
            Transition("select", "credit", "idle",
                       guard=self._guard_select, action=self._action_select),
            Transition("cancel", "credit", "idle",
                       action=self._action_cancel),
            Transition("service", "idle", "maintenance"),
            Transition("restock", "maintenance", "maintenance",
                       action=self._action_restock),
            Transition("resume", "maintenance", "idle"),
        ]
        self.machine = Machine(states, transitions, "idle", context=self)

    # -- fsm hooks ---------------------------------------------------------

    def _action_insert(self, machine: Machine, event) -> None:
        self._credit += event.data["coin"]

    def _guard_select(self, machine: Machine, event) -> bool:
        code = event.data["code"]
        if code not in self._prices:
            raise KeyError(code)
        if self._stock[code] <= 0:
            raise SoldOut(code)
        return self._credit >= self._prices[code]

    def _action_select(self, machine: Machine, event) -> None:
        code = event.data["code"]
        price = self._prices[code]
        change = _payout(self._credit - price)
        self._stock[code] -= 1
        self._sold[code] = self._sold.get(code, 0) + 1
        self._revenue += price
        self._credit = 0
        event.data["change"] = change
        self._change = change

    def _action_cancel(self, machine: Machine, event) -> None:
        refund = _payout(self._credit)
        self._credit = 0
        event.data["change"] = refund
        self._change = refund

    def _action_restock(self, machine: Machine, event) -> None:
        code = event.data["code"]
        qty = event.data["qty"]
        price = event.data.get("price")
        if code not in self._prices:
            self._prices[code] = int(price)
            self._stock[code] = 0
        self._stock[code] += qty
        if price is not None:
            self._prices[code] = int(price)

    # -- read-only views ---------------------------------------------------

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self._credit

    def stock(self, code: str) -> int:
        if code not in self._stock:
            raise KeyError(code)
        return self._stock[code]

    def price(self, code: str) -> int:
        if code not in self._prices:
            raise KeyError(code)
        return self._prices[code]

    def sales(self) -> dict[str, int]:
        return dict(self._sold)

    @property
    def revenue(self) -> int:
        return self._revenue

    # -- operations --------------------------------------------------------

    def insert(self, coin: int) -> int:
        if coin not in COINS:
            raise ValueError(f"coin {coin!r} is not accepted")
        self.machine.fire("insert", coin=coin)
        return self._credit

    def select(self, code: str) -> list[int]:
        if not self.machine.can_fire("select", code=code):
            if self.state != "credit":
                raise InvalidTransition(self.state, "select")
            raise InsufficientCredit(code)
        self.machine.fire("select", code=code)
        return list(self._change)

    def cancel(self) -> list[int]:
        self.machine.fire("cancel")
        return list(self._change)

    def service(self) -> None:
        self.machine.fire("service")

    def restock(self, code: str, qty: int, price: int | None = None) -> None:
        if qty < 1:
            raise ValueError("qty must be at least 1")
        if code not in self._prices and price is None:
            raise KeyError(code)
        self.machine.fire("restock", code=code, qty=qty, price=price)

    def resume(self) -> None:
        self.machine.fire("resume")
