library/loans.py
```python
"""Lending: checkout, holds, renewals, returns and fines."""

from collections import defaultdict
from dataclasses import dataclass
from datetime import date, timedelta

from .catalog import Catalog
from .fines import HOLD_PICKUP_DAYS, POLICY, due_date, fine_for


class LoanError(Exception):
    pass


class Blocked(LoanError):
    pass


class DuplicateLoan(LoanError):
    pass


class LimitReached(LoanError):
    pass


class NotAvailable(LoanError):
    pass


class RenewalRefused(LoanError):
    pass


@dataclass
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: date | None = None
    fine: int = 0


@dataclass
class _Hold:
    member_id: str
    isbn: str
    ready: bool = False
    deadline: date | None = None


class Library:
    def __init__(self, catalog: Catalog, clock) -> None:
        self._catalog = catalog
        self._clock = clock
        self._loans: dict[int, Loan] = {}
        self._next_loan_id = 1
        self._holds: dict[str, list[_Hold]] = {}
        self._setaside: dict[str, int] = defaultdict(int)
        self._balances: dict[str, int] = {}
        self._expiry_queue: list[tuple[date, int, int]] = []
        self._pending: dict[int, _Hold] = {}
        self._expiry_seq = 0

    def _today(self) -> date:
        return self._process_expiry(self._clock())

    def _process_expiry(self, today: date) -> date:
        while True:
            due = sorted(
                (d, seq, hid)
                for (d, seq, hid) in self._expiry_queue
                if d < today and hid in self._pending
            )
            if not due:
                break
            d, seq, hid = due[0]
            self._expiry_queue.remove((d, seq, hid))
            hold = self._pending.pop(hid)
            if hold.ready:
                self._expire(hold, d)
        return today

    def _expire(self, hold: _Hold, when: date) -> None:
        self._detach(hold)
        self._set_aside(hold.isbn)

    def _make_ready(self, hold: _Hold, when: date) -> None:
        hold.ready = True
        hold.deadline = when + timedelta(days=HOLD_PICKUP_DAYS)
        self._expiry_seq += 1
        self._expiry_queue.append((hold.deadline, self._expiry_seq, id(hold)))
        self._pending[id(hold)] = hold
        self._setaside[hold.isbn] += 1

    def _set_aside(self, isbn: str, on_loan: bool = False) -> None:
        free = self.available(isbn) + (1 if on_loan else 0)
        if free <= 0:
            return
        hold = next((h for h in self._holds.get(isbn, []) if not h.ready), None)
        if hold is not None:
            self._make_ready(hold, self._today())

    def available(self, isbn: str) -> int:
        book = self._catalog.book(isbn)
        today = self._today()
        active = sum(
            1
            for loan in self._loans.values()
            if loan.isbn == isbn and loan.returned is None
        )
        ready = sum(1 for h in self._holds.get(isbn, []) if h.ready)
        return book.copies - active - ready

    def checkout(self, member_id: str, isbn: str) -> Loan:
        member = self._catalog.member(member_id)
        self._catalog.book(isbn)
        today = self._today()
        policy = POLICY[member.kind]
        if self._balances.get(member_id, 0) > 0:
            raise Blocked(f"{member_id} has an unpaid balance")
        active = [
            loan
            for loan in self._loans.values()
            if loan.member_id == member_id and loan.returned is None
        ]
        if any(loan.isbn == isbn for loan in active):
            raise DuplicateLoan(f"{member_id} already has {isbn} on loan")
        if len(active) >= policy.max_loans:
            raise LimitReached(f"{member_id} has reached {policy.max_loans} loans")
        queue = self._holds.get(isbn, [])
        ready = next(
            (h for h in queue if h.ready and h.member_id == member_id), None
        )
        waiting = next(
            (
                h
                for h in self._holds.get(isbn, [])
                if not h.ready and h.member_id == member_id
            ),
            None,
        )
        if ready is not None:
            if ready.deadline is None or ready.deadline < today:
                raise NotAvailable(f"hold on {isbn} expired")
            self._detach(ready)
        elif self.available(isbn) <= 0:
            raise NotAvailable(f"no copies of {isbn} available")
        if waiting is not None:
            self._detach(waiting)
        loan = Loan(
            self._next_loan_id, member_id, isbn, today, due_date(today, policy.loan_days)
        )
        self._next_loan_id += 1
        self._loans[loan.loan_id] = loan
        return loan

    def _detach(self, hold: _Hold) -> None:
        queue = self._holds.get(hold.isbn)
        if queue is not None:
            try:
                queue.remove(hold)
            except ValueError:
                pass
        self._pending.pop(id(hold), None)
        if hold.ready:
            self._setaside[hold.isbn] -= 1

    def _remove_hold(self, hold: _Hold) -> None:
        self._detach(hold)
        self._set_aside(hold.isbn)

    def place_hold(self, member_id: str, isbn: str) -> int:
        self._catalog.member(member_id)
        self._catalog.book(isbn)
        today = self._today()
        active = any(
            loan.isbn == isbn and loan.member_id == member_id and loan.returned is None
            for loan in self._loans.values()
        )
        if active:
            raise DuplicateLoan(f"{member_id} already has {isbn} on loan")
        queue = self._holds.setdefault(isbn, [])
        if any(h.member_id == member_id for h in queue):
            raise DuplicateLoan(f"{member_id} already holds {isbn}")
        if self.available(isbn) > 0:
            raise LoanError(f"{isbn} is available; no hold needed")
        queue.append(_Hold(member_id, isbn))
        self._set_aside(isbn, on_loan=True)
        return len(queue)

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        self._catalog.member(member_id)
        self._catalog.book(isbn)
        self._today()
        queue = self._holds.get(isbn, [])
        hold = next((h for h in queue if h.member_id == member_id), None)
        if hold is None:
            raise KeyError(f"{member_id} has no hold on {isbn}")
        self._remove_hold(hold)

    def holds(self, isbn: str) -> list[str]:
        self._catalog.book(isbn)
        self._today()
        return [h.member_id for h in self._holds.get(isbn, [])]

    def hold_status(self, member_id: str, isbn: str):
        self._catalog.member(member_id)
        self._catalog.book(isbn)
        self._today()
        queue = self._holds.get(isbn, [])
        for index, hold in enumerate(queue, start=1):
            if hold.member_id == member_id:
                if hold.ready:
                    return ("ready", hold.deadline)
                return ("waiting", index)
        raise KeyError(f"{member_id} has no hold on {isbn}")

    def renew(self, loan_id: int) -> date:
        loan = self._loan(loan_id)
        today = self._today()
        if loan.returned is not None:
            raise LoanError(f"loan {loan_id} already returned")
        member = self._catalog.member(loan.member_id)
        policy = POLICY[member.kind]
        if today > loan.due:
            raise RenewalRefused(f"loan {loan_id} is overdue")
        if self._holds.get(loan.isbn):
            raise RenewalRefused(f"{loan.isbn} has holds")
        if loan.renewals >= policy.renewals:
            raise RenewalRefused(f"loan {loan_id} used all renewals")
        loan.due = due_date(loan.due, policy.loan_days)
        loan.renewals += 1
        return loan.due

    def checkin(self, loan_id: int) -> int:
        loan = self._loan(loan_id)
        today = self._today()
        if loan.returned is not None:
            raise LoanError(f"loan {loan_id} already returned")
        member = self._catalog.member(loan.member_id)
        fine = fine_for(member.kind, loan.due, today)
        loan.returned = today
        loan.fine = fine
        self._balances[loan.member_id] = self._balances.get(loan.member_id, 0) + fine
        self._set_aside(loan.isbn)
        return fine

    def accrued_fine(self, loan_id: int) -> int:
        loan = self._loan(loan_id)
        if loan.returned is not None:
            return loan.fine
        member = self._catalog.member(loan.member_id)
        return fine_for(member.kind, loan.due, self._today())

    def balance(self, member_id: str) -> int:
        self._catalog.member(member_id)
        return self._balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        self._catalog.member(member_id)
        if amount <= 0:
            raise ValueError("amount must be positive")
        current = self._balances.get(member_id, 0)
        if amount > current:
            raise ValueError("amount exceeds balance")
        self._balances[member_id] = current - amount
        return current - amount

    def loans(self, member_id: str) -> list[Loan]:
        self._catalog.member(member_id)
        self._today()
        active = [
            loan
            for loan in self._loans.values()
            if loan.member_id == member_id and loan.returned is None
        ]
        return sorted(active, key=lambda loan: (loan.due, loan.loan_id))

    def overdue(self) -> list[Loan]:
        today = self._today()
        late = [
            loan
            for loan in self._loans.values()
            if loan.returned is None and loan.due < today
        ]
        return sorted(late, key=lambda loan: (loan.due, loan.loan_id))

    def _loan(self, loan_id: int) -> Loan:
        try:
            return self._loans[loan_id]
        except KeyError:
            raise KeyError(loan_id) from None
