"""Fine policy: loan periods, renewals, fines and the lending calendar."""

from dataclasses import dataclass
from datetime import date, timedelta

HOLD_PICKUP_DAYS = 3


@dataclass(frozen=True)
class Policy:
    max_loans: int
    loan_days: int
    renewals: int
    daily_fine: int
    fine_cap: int
    grace_days: int


POLICY: dict[str, Policy] = {
    "standard": Policy(5, 21, 2, 25, 1000, 0),
    "student": Policy(3, 14, 1, 10, 500, 2),
    "staff": Policy(10, 42, 3, 0, 0, 0),
}


def due_date(start: date, days: int) -> date:
    """Return start + days, pushing a Sunday result to the following Monday."""
    result = start + timedelta(days=days)
    if result.weekday() == 6:
        result += timedelta(days=1)
    return result


def fine_for(kind: str, due: date, returned: date) -> int:
    """Fine in cents for returning a loan of the given kind after its due date."""
    policy = POLICY[kind]
    late = (returned - due).days
    if late <= policy.grace_days:
        return 0
    return min(late * policy.daily_fine, policy.fine_cap)
