library/loans.py
```python
"""Circulation desk: availability, holds, loans, renewals, returns and fines."""

from dataclasses import dataclass, field
from datetime import date, timedelta

from .catalog import Catalog
from .fines import HOLD_PICKUP_DAYS, POLICY, due_date, fine_for


class LoanError(Exception):
    pass


class Blocked(LoanError):
    pass


class DuplicateLoan(LoanError):
    pass


class LimitReached(LoanError):
    pass


class NotAvailable(LoanError):
    pass


class RenewalRefused(LoanError):
    pass


@dataclass
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: date | None = None
    fine: int = 0


@dataclass
class _Hold:
    member_id: str
    state: str = "waiting"
    deadline: date | None = None


class Library:
    def __init__(self, catalog: Catalog, clock) -> None:
        self._catalog = catalog
        self._clock = clock
        self._loans: dict[int, Loan] = {}
        self._next_loan_id = 1
        self._queues: dict[str, list[_Hold]] = {}
        self._balances: dict[str, int] = {}

    # -- clock and expiry ------------------------------------------------

    def _today(self) -> date:
        today = self._clock()
        self._expire(today)
        return today

    def _expire(self, today: date) -> None:
        while True:
            earliest = None
            for queue in self._queues.values():
                for hold in queue:
                    if (
                        hold.state == "ready"
                        and hold.deadline is not None
                        and hold.deadline + timedelta(days=1) < today
                        and (earliest is None or hold.deadline < earliest)
                    ):
                        earliest = hold.deadline
            if earliest is None:
                return
            self._expire_on(earliest, today)

    def _expire_on(self, expiry: date, today: date) -> None:
        for isbn, queue in self._queues.items():
            while (
                queue
                and queue[0].state == "ready"
                and queue[0].deadline is not None
                and queue[0].deadline + timedelta(days=1) == expiry
            ):
                queue.pop(0)
                if queue and queue[0].state == "waiting":
                    hold = queue[0]
                    hold.state = "ready"
                    hold.deadline = due_date(expiry, HOLD_PICKUP_DAYS)

    def _queue(self, isbn: str) -> list[_Hold]:
        self._catalog.book(isbn)
        return self._queues.setdefault(isbn, [])

    # -- availability ------------------------------------------------------

    def _active(self, isbn: str) -> int:
        return sum(
            1
            for loan in self._loans.values()
            if loan.isbn == isbn and loan.returned is None
        )

    def _active_member_loans(self, member_id: str) -> list[Loan]:
        return [
            loan
            for loan in self._loans.values()
            if loan.member_id == member_id and loan.returned is None
        ]

    def available(self, isbn: str) -> int:
        self._today()
        book = self._catalog.book(isbn)
        ready = sum(
            1 for hold in self._queues.get(isbn, ()) if hold.state == "ready"
        )
        return book.copies - self._active(isbn) - ready

    # -- checkout ----------------------------------------------------------

    def checkout(self, member_id: str, isbn: str) -> Loan:
        today = self._today()
        member = self._catalog.member(member_id)
        self._catalog.book(isbn)
        policy = POLICY[member.kind]

        if self._balances.get(member_id, 0) > 0:
            raise Blocked("member has an unpaid fine balance")
        if any(
            loan.isbn == isbn
            for loan in self._active_member_loans(member_id)
        ):
            raise DuplicateLoan("member already has this isbn on loan")
        if len(self._active_member_loans(member_id)) >= policy.max_loans:
            raise LimitReached("member has reached the loan limit")

        queue = self._queues.get(isbn)
        hold = next(
            (h for h in queue or () if h.member_id == member_id), None
        )
        if hold is not None and hold.state == "ready":
            if today > hold.deadline:
                raise NotAvailable("hold pickup window has passed")
            queue.remove(hold)
        elif self.available(isbn) <= 0:
            raise NotAvailable("no copy available")
        elif hold is not None:
            queue.remove(hold)

        loan = Loan(
            loan_id=self._next_loan_id,
            member_id=member_id,
            isbn=isbn,
            start=today,
            due=due_date(today, policy.loan_days),
        )
        self._next_loan_id += 1
        self._loans[loan.loan_id] = loan
        return loan

    # -- holds -------------------------------------------------------------

    def place_hold(self, member_id: str, isbn: str) -> int:
        self._today()
        self._catalog.member(member_id)
        if any(
            loan.isbn == isbn
            for loan in self._active_member_loans(member_id)
        ):
            raise DuplicateLoan("member already has this isbn on loan")
        queue = self._queue(isbn)
        if any(h.member_id == member_id for h in queue):
            raise DuplicateLoan("member already holds this isbn")
        if self.available(isbn) > 0:
            raise LoanError("copies are available; no hold needed")
        queue.append(_Hold(member_id))
        return len(queue)

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        today = self._today()
        self._catalog.member(member_id)
        queue = self._queue(isbn)
        hold = next((h for h in queue if h.member_id == member_id), None)
        if hold is None:
            raise KeyError("no hold for this member and isbn")
        index = queue.index(hold)
        was_ready = hold.state == "ready"
        queue.remove(hold)
        if was_ready and index < len(queue):
            nxt = queue[index]
            if nxt.state == "waiting":
                nxt.state = "ready"
                nxt.deadline = due_date(today, HOLD_PICKUP_DAYS)

    def holds(self, isbn: str) -> list[str]:
        self._today()
        return [h.member_id for h in self._queue(isbn)]

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, date | int]:
        self._today()
        self._catalog.member(member_id)
        queue = self._queue(isbn)
        index = next(
            (i for i, h in enumerate(queue) if h.member_id == member_id), None
        )
        if index is None:
            raise KeyError("no hold for this member and isbn")
        hold = queue[index]
        if hold.state == "ready":
            return ("ready", hold.deadline)
        return ("waiting", index + 1)

    # -- renew and return ----------------------------------------------------

    def _loan(self, loan_id: int) -> Loan:
        return self._loans[loan_id]

    def renew(self, loan_id: int) -> date:
        today = self._today()
        loan = self._loan(loan_id)
        if loan.returned is not None:
            raise LoanError("loan was already returned")
        policy = POLICY[self._catalog.member(loan.member_id).kind]
        if today > loan.due:
            raise RenewalRefused("loan is overdue")
        if self._queues.get(loan.isbn):
            raise RenewalRefused("isbn is on hold")
        if loan.renewals >= policy.renewals:
            raise RenewalRefused("no renewals left")
        loan.renewals += 1
        loan.due = due_date(loan.due, policy.loan_days)
        return loan.due

    def checkin(self, loan_id: int) -> int:
        today = self._today()
        loan = self._loan(loan_id)
        if loan.returned is not None:
            raise LoanError("loan was already returned")
        kind = self._catalog.member(loan.member_id).kind
        fine = fine_for(kind, loan.due, today)
        loan.returned = today
        loan.fine = fine
        self._balances[loan.member_id] = (
            self._balances.get(loan.member_id, 0) + fine
        )
        queue = self._queues.get(loan.isbn)
        if queue and queue[0].state == "waiting":
            hold = queue[0]
            hold.state = "ready"
            hold.deadline = due_date(today, HOLD_PICKUP_DAYS)
        return fine

    def accrued_fine(self, loan_id: int) -> int:
        today = self._today()
        loan = self._loan(loan_id)
        if loan.returned is not None:
            return loan.fine
        kind = self._catalog.member(loan.member_id).kind
        return fine_for(kind, loan.due, today)

    # -- money -------------------------------------------------------------

    def balance(self, member_id: str) -> int:
        self._today()
        self._catalog.member(member_id)
        return self._balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        self._today()
        self._catalog.member(member_id)
        if amount <= 0:
            raise ValueError("amount must be positive")
        current = self._balances.get(member_id, 0)
        if amount > current:
            raise ValueError("amount exceeds balance")
        self._balances[member_id] = current - amount
        return current - amount

    # -- views -------------------------------------------------------------

    def loans(self, member_id: str) -> list[Loan]:
        self._today()
        self._catalog.member(member_id)
        active = self._active_member_loans(member_id)
        active.sort(key=lambda loan: (loan.due, loan.loan_id))
        return active

    def overdue(self) -> list[Loan]:
        today = self._today()
        late = [
            loan
            for loan in self._loans.values()
            if loan.returned is None and loan.due < today
        ]
        late.sort(key=lambda loan: (loan.due, loan.loan_id))
        return late
