import re

_REF_RE = re.compile(r'([A-Za-z]+)([0-9]+)')


class FormulaError(ValueError):
    pass


class ErrorValue(str):
    pass


ERROR = ErrorValue('#ERROR!')
CYCLE = ErrorValue('#CYCLE!')


class Number:
    __slots__ = ('value',)

    def __init__(self, value):
        self.value = value


class Ref:
    __slots__ = ('name',)

    def __init__(self, name):
        self.name = name


class Unary:
    __slots__ = ('op', 'operand')

    def __init__(self, op, operand):
        self.op = op
        self.operand = operand


class Binary:
    __slots__ = ('op', 'left', 'right')

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


_TOKEN_RE = re.compile(r'[A-Za-z]+[0-9]+|[0-9]+(?:\.[0-9]+)?|[()+\-*/]|\S')


def _tokenize(source):
    tokens = []
    pos = 0
    n = len(source)
    while pos < n:
        ch = source[pos]
        if ch.isspace():
            pos += 1
            continue
        match = _TOKEN_RE.match(source, pos)
        if match is None:
            raise FormulaError(f'invalid character: {source[pos]!r}')
        token = match.group(0)
        if len(token) == 1 and not token.isalnum() and token not in '+-*/()':
            raise FormulaError(f'invalid character: {token!r}')
        if token[0].isdigit() and '.' in token and token.endswith('.'):
            raise FormulaError('number cannot end with a dot')
        tokens.append(token)
        pos = match.end()
    return tokens


def _parse_ref(token):
    match = _REF_RE.fullmatch(token)
    letters, digits = match.group(1), match.group(2)
    if len(letters) > 1:
        raise FormulaError(f'invalid reference: {token!r}')
    if digits[0] == '0' or not (1 <= int(digits) <= 999):
        raise FormulaError(f'invalid reference: {token!r}')
    return Ref(letters.upper() + digits)


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self):
        token = self.peek()
        if token is None:
            raise FormulaError('unexpected end of formula')
        self.pos += 1
        return token

    def parse(self):
        node = self.expr()
        if self.pos != len(self.tokens):
            raise FormulaError(f'unexpected token: {self.peek()!r}')
        return node

    def expr(self):
        node = self.term()
        while self.peek() in ('+', '-'):
            op = self.next()
            node = Binary(op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in ('*', '/'):
            op = self.next()
            node = Binary(op, node, self.unary())
        return node

    def unary(self):
        token = self.peek()
        if token in ('+', '-'):
            self.next()
            return Unary(token, self.unary())
        return self.primary()

    def primary(self):
        token = self.next()
        if token == '(':
            node = self.expr()
            if self.next() != ')':
                raise FormulaError('expected closing parenthesis')
            return node
        if token[0].isdigit():
            if '.' in token:
                return Number(float(token))
            return Number(int(token))
        if token[0].isalpha():
            return _parse_ref(token)
        raise FormulaError(f'unexpected token: {token!r}')


def parse_formula(source):
    if not isinstance(source, str):
        raise FormulaError('formula must be a string')
    if source.strip() == '':
        raise FormulaError('empty formula')
    return _Parser(_tokenize(source)).parse()


def references(tree):
    result = set()
    stack = [tree]
    while stack:
        node = stack.pop()
        if isinstance(node, Ref):
            result.add(node.name)
        elif isinstance(node, Unary):
            stack.append(node.operand)
        elif isinstance(node, Binary):
            stack.append(node.left)
            stack.append(node.right)
    return result


def evaluate(tree, lookup):
    if isinstance(tree, Number):
        return tree.value
    if isinstance(tree, Ref):
        value = lookup(tree.name)
        return 0 if value is None else value
    if isinstance(tree, Unary):
        value = evaluate(tree.operand, lookup)
        if isinstance(value, ErrorValue):
            return value
        if isinstance(value, str):
            return ERROR
        if tree.op == '-':
            return -value
        return +value
    left = evaluate(tree.left, lookup)
    right = evaluate(tree.right, lookup)
    if isinstance(left, ErrorValue):
        return left
    if isinstance(right, ErrorValue):
        return right
    if isinstance(left, str) or isinstance(right, str):
        return ERROR
    op = tree.op
    if op == '+':
        result = left + right
    elif op == '-':
        result = left - right
    elif op == '*':
        result = left * right
    else:
        if right == 0:
            return ERROR
        result = left / right
    if (
        op != '/'
        and isinstance(result, int)
        and isinstance(left, float)
        and isinstance(right, float)
    ):
        result = float(result)
    return result
