class DependencyGraph:
    def __init__(self):
        self._forward = {}
        self._reverse = {}

    def set_dependencies(self, cell, precedents):
        old = self._forward.get(cell, set())
        for precedent in old:
            deps = self._reverse.get(precedent)
            if deps is not None:
                deps.discard(cell)
                if not deps:
                    del self._reverse[precedent]
        new = set(precedents)
        if new:
            self._forward[cell] = new
            for precedent in new:
                self._reverse.setdefault(precedent, set()).add(cell)
        else:
            self._forward.pop(cell, None)

    def precedents(self, cell):
        return set(self._forward.get(cell, ()))

    def dependents(self, cell):
        return set(self._reverse.get(cell, ()))

    def all_dependents(self, cell):
        result = set()
        stack = [cell]
        while stack:
            current = stack.pop()
            for dependent in self._reverse.get(current, ()):
                if dependent not in result:
                    result.add(dependent)
                    stack.append(dependent)
        return result

    def cycle_cells(self):
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {}
        on_cycle = set()

        def visit(start):
            stack = [(start, iter(self._forward.get(start, ())))]
            path = [start]
            color[start] = GRAY
            while stack:
                node, iterator = stack[-1]
                matched = False
                for precedent in iterator:
                    state = color.get(precedent, WHITE)
                    if state == WHITE:
                        color[precedent] = GRAY
                        path.append(precedent)
                        stack.append((precedent, iter(self._forward.get(precedent, ()))))
                        matched = True
                        break
                    if state == GRAY:
                        on_cycle.add(precedent)
                        for index in range(len(path) - 1, -1, -1):
                            on_cycle.add(path[index])
                            if path[index] == precedent:
                                break
                if matched:
                    continue
                stack.pop()
                path.pop()
                color[node] = BLACK

        for node in list(self._forward):
            if color.get(node, WHITE) == WHITE:
                visit(node)
        return on_cycle
