import re
from collections import deque

from .formula import (
    CYCLE,
    ErrorValue,
    evaluate,
    parse_formula,
    references,
)
from .graph import DependencyGraph

_NAME_RE = re.compile(r'^([A-Za-z])([1-9][0-9]{0,2})$')
_NUMBER_RE = re.compile(r'^-?[0-9]+(\.[0-9]+)?$')


def _validate(name):
    if not isinstance(name, str):
        raise ValueError(f'invalid cell name: {name!r}')
    match = _NAME_RE.match(name)
    if match is None:
        raise ValueError(f'invalid cell name: {name!r}')
    return match.group(1).upper() + match.group(2)


def _sort_key(cell):
    return (int(cell[1:]), cell[0])


class Sheet:
    def __init__(self):
        self._raw = {}
        self._values = {}
        self._graph = DependencyGraph()
        self.evaluations = 0

    def set(self, name, raw):
        cell = _validate(name)
        if not isinstance(raw, str):
            raise TypeError('cell input must be a string')
        if raw.startswith('='):
            tree = parse_formula(raw[1:])
            self._raw[cell] = raw
            self._values.pop(cell, None)
            self._graph.set_dependencies(cell, references(tree))
        elif raw == '':
            self._raw.pop(cell, None)
            self._values.pop(cell, None)
            self._graph.set_dependencies(cell, ())
        elif _NUMBER_RE.match(raw.strip()):
            text = raw.strip()
            self._raw[cell] = raw
            self._values[cell] = float(text) if '.' in text else int(text)
            self._graph.set_dependencies(cell, ())
        else:
            self._raw[cell] = raw
            self._values[cell] = raw
            self._graph.set_dependencies(cell, ())
        affected = self._recompute(cell)
        return sorted(affected, key=_sort_key)

    def _recompute(self, start):
        affected = self._graph.all_dependents(start)
        affected.add(start)
        affected = {node for node in affected if node in self._raw}
        cycle_cells = self._graph.cycle_cells()
        todo = affected - cycle_cells
        formula_todo = {node for node in todo if self._raw[node].startswith('=')}
        # cells inside a cycle whose own formula input did not change keep
        # their stored value: the cycle is only re-checked when the changed
        # cell itself belongs to it
        if start not in cycle_cells:
            formula_todo = {
                node
                for node in formula_todo
                if not any(p in cycle_cells for p in self._graph.precedents(node))
            }
        indegree = {}
        for node in formula_todo:
            count = 0
            for precedent in self._graph.precedents(node):
                if precedent in formula_todo:
                    count += 1
            indegree[node] = count
        order = []
        ready = deque(
            sorted(
                (node for node, count in indegree.items() if count == 0),
                key=_sort_key,
            )
        )
        while ready:
            node = ready.popleft()
            order.append(node)
            for dependent in self._graph.dependents(node):
                if dependent in indegree:
                    indegree[dependent] -= 1
                    if indegree[dependent] == 0:
                        ready.append(dependent)
        for node in order:
            tree = parse_formula(self._raw[node][1:])
            self._values[node] = evaluate(tree, self._value_of)
            self.evaluations += 1
        for node in affected:
            if node in cycle_cells:
                self._values[node] = CYCLE
        return affected

    def _value_of(self, name):
        if self._raw.get(name, '').startswith('=') and name not in self._values:
            return CYCLE
        return self._values.get(name)

    def get(self, name):
        cell = _validate(name)
        value = self._values.get(cell)
        if isinstance(value, ErrorValue):
            return ErrorValue(value)
        return value

    def raw(self, name):
        cell = _validate(name)
        return self._raw.get(cell, '')

    def cells(self):
        return sorted(self._raw, key=_sort_key)
