from .versions import Range, Version


class PackageIndex:
    def __init__(self):
        self._data = {}

    def add(self, name, version, requires=None):
        v = Version(version)
        ranges = {}
        if requires:
            for dep, spec in requires.items():
                ranges[dep] = Range(spec)
        releases = self._data.setdefault(name, {})
        if v in releases:
            raise ValueError(f"{name} {v} is already in the index")
        releases[v] = ranges

    def versions(self, name):
        releases = self._data.get(name)
        if not releases:
            return []
        return sorted(releases, reverse=True)

    def requirements(self, name, version):
        releases = self._data.get(name)
        if not releases or version not in releases:
            raise KeyError(f"{name} {version}")
        return dict(releases[version])

    @classmethod
    def from_dict(cls, data):
        index = cls()
        for name, releases in data.items():
            for version, requires in releases.items():
                index.add(name, version, requires)
        return index
