from .versions import Range


class ResolutionError(Exception):
    def __init__(self, package, explanation):
        super().__init__(explanation)
        self.package = package
        self.explanation = explanation


def resolve(index, requirements):
    root = {}
    for name in requirements:
        root[name] = Range(requirements[name])
    order = sorted(root)
    selected = {}
    failure = {"found": False, "package": None, "lines": None}
    result = _search(index, root, order, selected, failure)
    if result is not None:
        return result
    return _fail(failure["package"], failure["lines"])


def _search(index, root, order, selected, failure):
    name = next((n for n in order if n not in selected), None)
    if name is None:
        return dict(selected)

    constraints = []
    if name in root:
        constraints.append(("<root>", root[name]))
    for req_name, req_version in selected.items():
        requirements = index.requirements(req_name, req_version)
        if name in requirements:
            requirer = f"{req_name} {req_version}"
            constraints.append((requirer, requirements[name]))

    versions = index.versions(name)
    diagnostics = []
    for version in versions:
        if any(not rng.contains(version) for _, rng in constraints):
            diagnostics.append(f"  {name} {version} is excluded by the constraints")
            continue
        deps = index.requirements(name, version)
        dep_conflict = None
        for dep in sorted(deps):
            rng = deps[dep]
            if dep in selected and not rng.contains(selected[dep]):
                dep_conflict = (
                    f"  {name} {version} requires {dep} {rng}, "
                    f"but {dep} {selected[dep]} is selected"
                )
                break
        if dep_conflict is not None:
            diagnostics.append(dep_conflict)
            continue

        added = sorted(dep for dep in deps if dep not in order)
        selected[name] = version
        order.extend(added)
        result = _search(index, root, order, selected, failure)
        if result is not None:
            return result
        del selected[name]
        for dep in added:
            order.remove(dep)
        if failure["found"]:
            return None

    if not failure["found"]:
        lines = [f"cannot resolve {name}"]
        for requirer, rng in constraints:
            lines.append(f"  {requirer} requires {name} {rng}")
        if not versions:
            lines.append(f"  no versions of {name} are known")
        else:
            lines.extend(diagnostics)
        failure["found"] = True
        failure["package"] = name
        failure["lines"] = lines
    return None


def _fail(package, lines):
    raise ResolutionError(package, "\n".join(lines))
