import re

_VERSION_RE = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$")
_CONSTRAINT_RE = re.compile(
    r"^(\^|~|==|!=|>=|<=|>|<)?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$"
)


class Version:
    __slots__ = ("major", "minor", "patch")

    def __init__(self, text):
        if not isinstance(text, str):
            raise ValueError(f"invalid version: {text!r}")
        match = _VERSION_RE.match(text)
        if match is None:
            raise ValueError(f"invalid version: {text!r}")
        self.major = int(match.group(1))
        self.minor = int(match.group(2))
        self.patch = int(match.group(3))

    @property
    def _key(self):
        return (self.major, self.minor, self.patch)

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self):
        return f"Version({str(self)!r})"

    def __hash__(self):
        return hash(self._key)

    def __eq__(self, other):
        if isinstance(other, Version):
            return self._key == other._key
        return NotImplemented

    def __ne__(self, other):
        if isinstance(other, Version):
            return self._key != other._key
        return NotImplemented

    def __lt__(self, other):
        if isinstance(other, Version):
            return self._key < other._key
        return NotImplemented

    def __le__(self, other):
        if isinstance(other, Version):
            return self._key <= other._key
        return NotImplemented

    def __gt__(self, other):
        if isinstance(other, Version):
            return self._key > other._key
        return NotImplemented

    def __ge__(self, other):
        if isinstance(other, Version):
            return self._key >= other._key
        return NotImplemented


class Range:
    __slots__ = ("_spec", "_constraints")

    def __init__(self, spec):
        if not isinstance(spec, str):
            raise ValueError(f"invalid range: {spec!r}")
        constraints = []
        for part in spec.split(","):
            stripped = part.strip()
            if not stripped:
                raise ValueError(f"invalid range: {spec!r}")
            constraints.append(_parse_constraint(stripped, spec))
        if not constraints:
            raise ValueError(f"invalid range: {spec!r}")
        self._spec = "".join(spec.split())
        self._constraints = constraints

    def contains(self, version):
        return all(test(version) for test in self._constraints)

    def __contains__(self, version):
        return self.contains(version)

    def __str__(self):
        return self._spec

    def __repr__(self):
        return f"Range({self._spec!r})"

    def __eq__(self, other):
        if isinstance(other, Range):
            return self._spec == other._spec
        return NotImplemented

    def __hash__(self):
        return hash(self._spec)


def _parse_constraint(text, spec):
    if text == "*":
        return lambda version: True
    match = _CONSTRAINT_RE.match(text)
    if match is None:
        raise ValueError(f"invalid range: {spec!r}")
    operator = match.group(1)
    target = Version(f"{match.group(2)}.{match.group(3)}.{match.group(4)}")
    if operator in (None, "=="):
        return lambda version, t=target: version == t
    if operator == "!=":
        return lambda version, t=target: version != t
    if operator == ">":
        return lambda version, t=target: version > t
    if operator == ">=":
        return lambda version, t=target: version >= t
    if operator == "<":
        return lambda version, t=target: version < t
    if operator == "<=":
        return lambda version, t=target: version <= t
    if operator == "~":
        upper = Version(f"{target.major}.{target.minor + 1}.0")
        return lambda version, lo=target, hi=upper: lo <= version < hi
    if operator == "^":
        return _caret_constraint(target)
    raise ValueError(f"invalid range: {spec!r}")


def _caret_constraint(target):
    upper = _caret_upper(target)
    return lambda version, lo=target, hi=upper: lo <= version < hi


def _caret_upper(target):
    if target.major != 0:
        return Version(f"{target.major + 1}.0.0")
    if target.minor != 0:
        return Version(f"0.{target.minor + 1}.0")
    return Version(f"0.0.{target.patch + 1}")
