from .versions import Range, Version


class ResolutionError(Exception):
    def __init__(self, package, explanation):
        super().__init__(explanation)
        self.package = package
        self.explanation = explanation


ROOT = "<root>"


def _requirer_name(name, version):
    return f"{name} {version}"


class _Searcher:
    def __init__(self, index, root_ranges, order):
        self.index = index
        self.root_ranges = root_ranges
        self.order = order
        self.selected = {}
        self.deepest = None

    def _select(self, name, version):
        self.selected[name] = version
        added = [
            dep
            for dep in sorted(self.index.requirements(name, version))
            if dep not in self.order
        ]
        self.order.extend(added)
        return added

    def _unselect(self, name, added):
        del self.selected[name]
        for dep in added:
            self.order.remove(dep)

    def _constraints(self, name):
        constraints = []
        spec = self.root_ranges.get(name)
        if spec is not None:
            constraints.append((ROOT, spec))
        for pkg, version in self.selected.items():
            if pkg == name:
                continue
            spec = self.index.requirements(pkg, version).get(name)
            if spec is not None:
                constraints.append((_requirer_name(pkg, version), spec))
        return constraints

    def _failures(self, constraints, name, selected):
        lines = [f"cannot resolve {name}"]
        for requirer, spec in constraints:
            lines.append(f"  {requirer} requires {name} {spec}")
        known = self.index.versions(name)
        if not known:
            lines.append(f"  no versions of {name} are known")
            return lines
        for version in known:
            if not all(spec.contains(version) for _, spec in constraints):
                lines.append(f"  {name} {version} is excluded by the constraints")
                continue
            conflict = None
            for dep, spec in sorted(
                self.index.requirements(name, version).items()
            ):
                chosen = selected.get(dep)
                if chosen is not None and not spec.contains(chosen):
                    conflict = (dep, spec, chosen)
                    break
            if conflict is None:
                lines.append(f"  {name} {version} is excluded by the constraints")
            else:
                dep, spec, chosen = conflict
                lines.append(
                    f"  {name} {version} requires {dep} {spec}, "
                    f"but {dep} {chosen} is selected"
                )
        return lines

    def _attempt(self):
        name = None
        for candidate in self.order:
            if candidate not in self.selected:
                name = candidate
                break
        if name is None:
            return dict(self.selected), None
        constraints = self._constraints(name)
        tried = False
        for version in self.index.versions(name):
            if not all(spec.contains(version) for _, spec in constraints):
                continue
            acceptable = True
            for dep, spec in self.index.requirements(name, version).items():
                chosen = self.selected.get(dep)
                if chosen is not None and not spec.contains(chosen):
                    acceptable = False
                    break
            if not acceptable:
                continue
            tried = True
            added = self._select(name, version)
            result, failure = self._attempt()
            if failure is None:
                return result, None
            self._unselect(name, added)
        if tried:
            return None, (name, constraints, dict(self.selected))
        failure = (name, constraints, dict(self.selected))
        depth = len(self.selected)
        if self.deepest is None or self.deepest[3] < depth:
            self.deepest = failure + (depth,)
        return None, self.deepest[:3]

    def run(self):
        result, failure = self._attempt()
        if failure is None:
            return result
        name, constraints, at_failure = failure
        raise ResolutionError(
            name, "\n".join(self._failures(constraints, name, at_failure))
        )


def resolve(index, requirements):
    root_ranges = {}
    for name, spec in requirements.items():
        root_ranges[name] = Range(spec)
    searcher = _Searcher(index, root_ranges, sorted(root_ranges))
    return searcher.run()
