import re


class Version:
    _NUMBER = re.compile(r"0|[1-9][0-9]*")

    def __init__(self, text):
        if not isinstance(text, str):
            raise ValueError(f"invalid version: {text!r}")
        parts = text.split(".")
        if len(parts) != 3:
            raise ValueError(f"invalid version: {text!r}")
        numbers = []
        for part in parts:
            if self._NUMBER.fullmatch(part) is None:
                raise ValueError(f"invalid version: {text!r}")
            numbers.append(int(part))
        self.major, self.minor, self.patch = numbers
        self._text = f"{self.major}.{self.minor}.{self.patch}"

    @classmethod
    def _partial(cls, text):
        if not isinstance(text, str):
            raise ValueError(f"invalid version: {text!r}")
        parts = text.split(".")
        if not 1 <= len(parts) <= 3:
            raise ValueError(f"invalid version: {text!r}")
        numbers = []
        for part in parts:
            if cls._NUMBER.fullmatch(part) is None:
                raise ValueError(f"invalid version: {text!r}")
            numbers.append(int(part))
        version = cls.__new__(cls)
        version.major = numbers[0]
        version.minor = numbers[1] if len(numbers) > 1 else 0
        version.patch = numbers[2] if len(numbers) > 2 else 0
        version._text = f"{version.major}.{version.minor}.{version.patch}"
        return version

    def __str__(self):
        return self._text

    def __repr__(self):
        return f"Version({self._text!r})"

    def _key(self):
        return (self.major, self.minor, self.patch)

    def __hash__(self):
        return hash(self._key())

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() == other._key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() < other._key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() <= other._key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() > other._key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._key() >= other._key()


_CARET = re.compile(r"\^(.+)$")
_TILDE = re.compile(r"~(.+)$")
_COMPARISON = re.compile(r"(==|!=|>=|<=|>|<)(.+)$")


def _parse_constraint(text):
    if text == "*":
        return lambda version: True
    match = _CARET.fullmatch(text)
    if match:
        lower = Version._partial(match.group(1))
        if lower.major != 0:
            upper = Version(f"{lower.major + 1}.0.0")
        elif lower.minor != 0:
            upper = Version(f"0.{lower.minor + 1}.0")
        else:
            upper = Version(f"0.0.{lower.patch + 1}")
        return lambda version, lo=lower, hi=upper: lo <= version < hi
    match = _TILDE.fullmatch(text)
    if match:
        lower = Version._partial(match.group(1))
        upper = Version(f"{lower.major}.{lower.minor + 1}.0")
        return lambda version, lo=lower, hi=upper: lo <= version < hi
    match = _COMPARISON.fullmatch(text)
    if match:
        op, ver = match.group(1), match.group(2)
        target = Version(ver)
        if op == "==":
            return lambda version, t=target: version == t
        if op == "!=":
            return lambda version, t=target: version != t
        if op == ">":
            return lambda version, t=target: version > t
        if op == ">=":
            return lambda version, t=target: version >= t
        if op == "<":
            return lambda version, t=target: version < t
        return lambda version, t=target: version <= t
    target = Version(text)
    return lambda version, t=target: version == t


class Range:
    def __init__(self, spec):
        if not isinstance(spec, str):
            raise ValueError(f"invalid range spec: {spec!r}")
        compact = "".join(spec.split())
        if compact == "":
            raise ValueError("empty range spec")
        self._text = compact
        self._checks = []
        for part in compact.split(","):
            if part == "":
                raise ValueError("empty constraint in range spec")
            self._checks.append(_parse_constraint(part))

    def contains(self, version):
        if not isinstance(version, Version):
            raise TypeError("version must be a Version")
        return all(check(version) for check in self._checks)

    def __contains__(self, version):
        return self.contains(version)

    def __str__(self):
        return self._text

    def __repr__(self):
        return f"Range({self._text!r})"
